-- Canónica de distribuidores de robots en Colombia y Latinoamérica.
-- El path vive en el código (campo bloqueado). Aquí se alinea el copy del CMS.

UPDATE public.landings AS landing
SET contenido_es = $ime_landing${"tag":"Distribuidores de robots","title":"Distribuidores de robots en Colombia y Latinoamérica | I-ME","description":"Distribuidores de robots e ingeniería robótica en Colombia y Latinoamérica: limpieza autónoma, recepción, telepresencia y logística con LiDAR SLAM. Cotice con I-ME.","h1":"Distribuidores de Robots e Ingeniería Robótica en Colombia y Latinoamérica","lead":"I-ME distribuye robots de servicio, limpieza autónoma, recepción, telepresencia y logística AMR para clínicas, hoteles, universidades y empresas en Colombia, y atiende proyectos de ingeniería robótica en Latinoamérica. Ocho modelos están en catálogo. Otras arquitecturas se ingenian bajo proyecto, sin dar de alta SKUs nuevos.","formIntro":"Institución, ciudad y el cuello de botella: recepción, telepresencia, logística AMR, limpieza o integración con ascensores. Respondemos con los modelos publicados y, si aplica, un alcance de ingeniería.","primaryCta":"Cotizar ingeniería robótica","secondaryCta":"WhatsApp","tertiaryCta":"Ver la familia de robots","heroImage":"/assets/img/robots-asistenciales-atencion-institucional-colombia.webp","heroImageAlt":"Robot humanoide asistencial en un lobby clínico, referencia visual de robótica de servicio en Colombia","heroImageWidth":1168,"heroImageHeight":784,"relatedGuides":[{"title":"Guía: robots asistenciales y carga operativa","href":"/es/conocimiento/robots-asistenciales-atencion-reduccion-carga-personal/"}],"problemTitle":"Operación real, no un lobby de ciencia ficción","problemBody":"Las instituciones buscan distribuidores de robots en Colombia para filas de recepción, recorridos de insumos, presencia remota o limpieza de grandes superficies. La ingeniería robótica solo avanza si el mapa, los ascensores y el responsable de operación están definidos.","solutionsTitle":"Empresas de robótica: qué resuelve el catálogo","solutions":[{"pain":"Recepción, turnos y preguntas repetidas","help":"PadBot X3, PadBot X2 y Cruzr cubren orientación, Q&A e interacción. Cruzr añade brazos y Open API."},{"pain":"Rondas y telepresencia médica","help":"PadBot P2 publica videollamada HD, 10 h de autonomía y sensores anticaída para conectar al especialista con la sala."},{"pain":"Logística intrahospitalaria y alimentos","help":"PadBot W2 cierra el gabinete con PIN o QR. PadBot W3s reparte en tres bandejas con pantalla Full HD."},{"pain":"Limpieza autónoma de suelos clínicos","help":"El robot C3 aspira, friega y pasa mopa, con estación de agua y ruido inferior a 70 dB."}],"audienceYes":["Clínicas, hospitales, hoteles, universidades y empresas con un flujo medible","Proyectos de recepción, telepresencia, AMR, limpieza o integración con ascensores","Quienes deciden o influyen en el presupuesto institucional"],"audienceNo":["Pacientes que buscan terapia personal","Quienes piden un resultado clínico o un retorno inventado","Consultas sin institución ni sede"],"situations":[{"title":"Robots de servicio","body":"Recepción, telepresencia, delivery y humanoide comercial publicados en catálogo."},{"title":"Ingeniería de edificio","body":"Mapa SLAM, E-Box, puertas automáticas y comisionamiento en la sede."},{"title":"Soluciones bajo proyecto","body":"Limpieza pesada, UV-C y logística cerrada, sin SKU nuevo."}],"scopeTitle":"Alcance con los pies en la tierra","scope":["Ocho robots del catálogo activo, con ficha y PDF del fabricante","Ingeniería de navegación LiDAR SLAM e integración IoT","Puesta en marcha y capacitación según propuesta","Garantía oficial del fabricante con soporte electromecánico y de integración local por I-ME en Colombia."],"requirementsTitle":"Para preparar la visita","requirements":["Institución y ciudad","Flujo a resolver y plazo","Planos o una descripción de ascensores, puertas y superficies"],"financingNote":"Hay financiación institucional orientativa. Tasas y plazos se confirman en la propuesta formal, no en esta página.","evidenceNote":"Solo se citan cifras de los manuales. Sin precios, sin registros INVIMA genéricos y sin códigos UNSPSC.","processTitle":"Cómo sigue I-ME","processSteps":["Escuchamos el edificio y el flujo","Elegimos modelos publicados o un alcance bajo proyecto","Levantamos el mapa y los puntos de ascensor","Cotizamos instalación, capacitación y soporte"],"faqs":[{"q":"¿Quiénes distribuyen robots de servicio, limpieza y telepresencia en Colombia?","a":"I-ME (International Medical Enterprise IME S.A.S.) distribuye en Colombia los ocho robots del catálogo activo: PadBot X3, PadBot X2, PadBot P2, PadBot W2, PadBot W3s, robot C3 de limpieza autónoma, PadBot T2 y Cruzr (AHuman Future). La cotización y el alcance de instalación se confirman por proyecto. WhatsApp +57 313 724 7353 · info@i-me.com.co."},{"q":"¿Cómo funciona la navegación LiDAR SLAM y la integración con ascensores y torniquetes?","a":"El mapa se construye con LiDAR láser Clase 1 (IEC 60825-1), visión RGB-D o estereoscópica, ultrasonido, infrarrojos anticaída y parachoques con parada de emergencia. En varias plantas se configuran puntos de espera y de abordaje de ascensor con el módulo IoT E-Box o una API Cloud, y puntos de control de acceso para puertas y torniquetes."},{"q":"¿Qué autonomía publican los robots PadBot y el robot de limpieza C3?","a":"Los manuales de PadBot X3, X2, P2, W2 y W3s publican 10 h de autonomía (el P2 añade 40 h en espera). El PadBot T2 publica 6 h (18 h en espera). El robot C3 publica de 2 a 3,5 h por ciclo, con batería extraíble de 46 Ah y recarga automática por debajo del 10 % o de 24 V. El resultado en cada sede depende del recorrido y del modo."},{"q":"¿Cómo es el soporte técnico en Bogotá, Medellín, Cali y Barranquilla?","a":"Garantía oficial del fabricante con soporte electromecánico y de integración local por I-ME en Colombia. El mantenimiento preventivo, los repuestos y la visita en Bogotá, Medellín, Cali, Barranquilla y el resto del país se definen en la propuesta. No publicamos plazos de entrega genéricos."},{"q":"¿Estos robots de recepción, telepresencia, logística o limpieza tienen registro INVIMA?","a":"No realizan diagnóstico, monitoreo clínico ni tratamiento sobre el paciente: operan como automatización, logística e infraestructura. La documentación aplicable se confirma por referencia, en el marco del Decreto 4725 cuando el equipo sea un dispositivo médico y de las normas de máquinas del manual (EN ISO 12100, EN 60335-2-72, IEC 60825-1, entre otras citadas en el C3). I-ME no publica un número de registro INVIMA genérico para la línea."},{"q":"¿I-ME distribuye robots en Colombia y también en Latinoamérica?","a":"El catálogo, la ingeniería de integración y el soporte electromecánico se operan desde Colombia, con visitas en Bogotá, Medellín, Cali, Barranquilla y el resto del país. I-ME también atiende proyectos de distribución e ingeniería robótica para instituciones en Latinoamérica; la logística y el alcance de cada sede se confirman en la propuesta. No publicamos sucursales ni plazos genéricos por país."}],"projectOptions":[{"value":"recepcion_ia","label":"Recepción, orientación e IA"},{"value":"telepresencia","label":"Telepresencia médica"},{"value":"logistica_amr","label":"Logística AMR y delivery"},{"value":"limpieza","label":"Limpieza autónoma"},{"value":"ingenieria_integracion","label":"Integración con ascensores y accesos"},{"value":"demo","label":"Quiero una demostración"}],"productsTitle":"Ocho robots en catálogo","productsNote":"Modelos reales. La demo confirma si encajan en el edificio."}$ime_landing$::jsonb,
    contenido_en = $ime_landing${"tag":"Robot distributors","title":"Robot Distributors in Colombia and Latin America | I-ME","description":"Robot distributors and robotics engineering in Colombia and Latin America: autonomous cleaning, reception, telepresence and logistics with LiDAR SLAM. Contact I-ME.","h1":"Robot Distributors and Robotics Engineering in Colombia and Latin America","lead":"I-ME distributes service, autonomous cleaning, reception, telepresence and AMR logistics robots for clinics, hotels, universities and companies in Colombia, and takes robotics engineering projects across Latin America. Eight models are in the catalog. Other architectures are engineered per project, without new SKUs.","formIntro":"Institution, city and the bottleneck: reception, telepresence, AMR logistics, cleaning or elevator integration. We answer with published models and, when it applies, an engineering scope.","primaryCta":"Request robotics engineering","secondaryCta":"WhatsApp","tertiaryCta":"Browse the robot family","heroImage":"/assets/img/robots-asistenciales-atencion-institucional-colombia.webp","heroImageAlt":"Assistive humanoid robot in a clinical lobby, a visual reference for service robotics in Colombia","heroImageWidth":1168,"heroImageHeight":784,"relatedGuides":[{"title":"Guide: assistive robots and task load","href":"/en/knowledge/robots-asistenciales-atencion-reduccion-carga-personal/"}],"problemTitle":"Real operations, not a science-fiction lobby","problemBody":"Institutions look for robot distributors in Colombia to fix reception queues, supply routes, remote presence or large-floor cleaning. Robotics engineering only moves forward when the map, the elevators and the operating owner are defined.","solutionsTitle":"What the catalog actually solves","solutions":[{"pain":"Reception, tickets and repeated questions","help":"PadBot X3, PadBot X2 and Cruzr cover wayfinding, Q&A and interaction. Cruzr adds arms and an Open API."},{"pain":"Rounds and medical telepresence","help":"PadBot P2 publishes HD video, 10 h runtime and cliff sensors so a specialist can join the room."},{"pain":"In-hospital logistics and meals","help":"PadBot W2 locks the cabinet with a PIN or QR. PadBot W3s delivers on three trays with a Full HD display."},{"pain":"Autonomous cleaning of clinical floors","help":"The C3 robot vacuums, mops and dust-mops, with a water station and noise under 70 dB."}],"audienceYes":["Clinics, hospitals, hotels, universities and companies with a measurable flow","Reception, telepresence, AMR, cleaning or elevator-integration projects","People who decide or influence the institutional budget"],"audienceNo":["Patients seeking personal therapy","Requests for a clinical outcome or an invented return","Inquiries without an institution or a site"],"situations":[{"title":"Service robots","body":"Reception, telepresence, delivery and a commercial humanoid published in the catalog."},{"title":"Building engineering","body":"SLAM map, E-Box, automatic doors and on-site commissioning."},{"title":"Project-only solutions","body":"Heavy cleaning, UV-C and closed logistics, without a new SKU."}],"scopeTitle":"Scope, stated plainly","scope":["Eight robots in the active catalog, with manufacturer sheet and PDF","LiDAR SLAM navigation engineering and IoT integration","Commissioning and training per proposal","Official manufacturer warranty with local electromechanical and integration support by I-ME in Colombia."],"requirementsTitle":"To prepare the visit","requirements":["Institution and city","Workflow to solve and timeline","Drawings or a description of elevators, doors and floors"],"financingNote":"Indicative institutional financing is available. Rates and terms are confirmed in the formal proposal, not on this page.","evidenceNote":"Only manual figures are cited. No prices, no generic INVIMA registrations and no UNSPSC codes.","processTitle":"How I-ME follows up","processSteps":["We listen to the building and the flow","We select published models or a project scope","We survey the map and elevator points","We quote installation, training and support"],"faqs":[{"q":"Who distributes service, cleaning and telepresence robots in Colombia?","a":"I-ME (International Medical Enterprise IME S.A.S.) distributes in Colombia the eight robots in the active catalog: PadBot X3, PadBot X2, PadBot P2, PadBot W2, PadBot W3s, the C3 autonomous cleaning robot, PadBot T2 and Cruzr (AHuman Future). Quote and installation scope are confirmed per project. WhatsApp +57 313 724 7353 · info@i-me.com.co."},{"q":"How do LiDAR SLAM navigation and elevator or turnstile integration work?","a":"The map is built with Class 1 LiDAR (IEC 60825-1), RGB-D or stereo vision, ultrasound, infrared cliff sensors and a bumper with emergency stop. Multi-floor jobs use elevator waiting and boarding points via the E-Box IoT module or a cloud API, plus access-control points for doors and turnstiles."},{"q":"What runtime do the PadBot robots and the C3 cleaning robot publish?","a":"PadBot X3, X2, P2, W2 and W3s manuals publish 10 h of runtime (P2 also lists 40 h standby). PadBot T2 publishes 6 h (18 h standby). The C3 robot publishes 2 to 3.5 h per cycle, with a 46 Ah removable battery and automatic recharge below 10% or 24 V. Results on site depend on the route and the mode."},{"q":"What does technical support look like in Bogotá, Medellín, Cali and Barranquilla?","a":"Official manufacturer warranty with local electromechanical and integration support by I-ME in Colombia. Preventive maintenance, spare parts and visits in Bogotá, Medellín, Cali, Barranquilla and the rest of the country are defined in the proposal. We do not publish generic lead times."},{"q":"Do these reception, telepresence, logistics or cleaning robots have an INVIMA registration?","a":"They do not diagnose, monitor or treat a patient: they operate as automation, logistics and infrastructure. Applicable documentation is confirmed per reference, under Decree 4725 when the unit is a medical device and under the machinery standards in the manual (EN ISO 12100, EN 60335-2-72, IEC 60825-1, among others cited for the C3). I-ME does not publish a generic INVIMA registration number for the line."},{"q":"Does I-ME distribute robots in Colombia and also in Latin America?","a":"The catalog, integration engineering and electromechanical support run from Colombia, with visits in Bogotá, Medellín, Cali, Barranquilla and the rest of the country. I-ME also takes distribution and robotics engineering projects for institutions in Latin America; logistics and scope for each site are confirmed in the proposal. We do not publish branches or generic lead times by country."}],"projectOptions":[{"value":"recepcion_ia","label":"Reception, wayfinding and AI"},{"value":"telepresencia","label":"Medical telepresence"},{"value":"logistica_amr","label":"AMR logistics and delivery"},{"value":"limpieza","label":"Autonomous cleaning"},{"value":"ingenieria_integracion","label":"Elevator and access integration"},{"value":"demo","label":"I want a demonstration"}],"productsTitle":"Eight catalog robots","productsNote":"Real models. A demo confirms whether they fit the building."}$ime_landing$::jsonb,
    version = landing.version + 1,
    publicado_at = NOW()
WHERE landing.tipo = 'campana'
  AND landing.clave = 'robotica_rehabilitacion'
  AND landing.contenido_es->>'title' IS DISTINCT FROM $ime_title$Distribuidores de robots en Colombia y Latinoamérica | I-ME$ime_title$;

INSERT INTO public.landings_historial (landing_id, version, contenido_es, contenido_en)
SELECT id, version, contenido_es, contenido_en
FROM public.landings
WHERE tipo = 'campana' AND clave = 'robotica_rehabilitacion'
ON CONFLICT (landing_id, version) DO NOTHING;

UPDATE public.articulos
SET cuerpo_es = replace(
      cuerpo_es,
      '(/es/robotica-rehabilitacion/)',
      '(/es/distribuidores-de-robots-e-ingenieria-robotica-en-colombia-y-latinoamerica/)'
    ),
    cuerpo_en = replace(
      cuerpo_en,
      '(/en/robotics-rehabilitation/)',
      '(/en/robot-distributors-and-robotics-engineering-in-colombia-and-latin-america/)'
    )
WHERE cuerpo_es LIKE '%(/es/robotica-rehabilitacion/)%'
   OR cuerpo_en LIKE '%(/en/robotics-rehabilitation/)%';
